#include "O2HLGTransfer.h"
#include <math.h>
#include <stdio.h>
#define CHECK(c) do { if (!(c)) { fprintf(stderr, "line %d: %s\n", __LINE__, #c); return 1; } } while (0)
static int closeTo(double actual, double expected, double tolerance) { return fabs(actual - expected) <= tolerance; }
int main(void) {
    /* Fixed independent Table 5 vectors, not values generated by tested helpers. */
    const double encoded[] = {0, 0.25, 0.5, 0.75, 1};
    const double scene[] = {0, 0.020833333333333333, 0.083333333333333333, 0.264962560421007, 1.00000002693481};
    double value;
    for (int i = 0; i < 5; i++) {
        CHECK(O2HLGInverseOETF(encoded[i], &value));
        CHECK(closeTo(value, scene[i], 6e-15));
    }
    CHECK(O2HLGInverseOETF(0.499999, &value) && closeTo(value, 0.083333000000333333, 6e-16));
    CHECK(O2HLGInverseOETF(0.500001, &value) && closeTo(value, 0.083333666667598638, 6e-16));
    CHECK(O2HLGOETF(0, &value) && value == 0);
    CHECK(O2HLGOETF(1.0/12, &value) && value == 0.5);
    CHECK(O2HLGOETF(1, &value) && closeTo(value, 0.999999995066131, 6e-15));
    const double invalid[] = {-1, 1.0001, NAN, INFINITY, -INFINITY};
    for (int i = 0; i < 5; i++) {
        value = 42; CHECK(!O2HLGInverseOETF(invalid[i], &value) && value == 42);
        CHECK(!O2HLGOETF(invalid[i], &value) && value == 42);
    }
    CHECK(!O2HLGOETF(0, NULL) && !O2HLGInverseOETF(0, NULL));
    double black[3] = {0,0,0}, white[3] = {1,1,1}, out[3];
    CHECK(O2HLGReferenceOOTF(black, 1000, out) && out[0] == 0 && out[1] == 0 && out[2] == 0);
    CHECK(O2HLGReferenceOOTF(white, 1000, out) && closeTo(out[0], 1000, 1e-10));
    double gray[3] = {0.5,0.5,0.5};
    CHECK(O2HLGReferenceEOTF(gray, 1000, out));
    CHECK(closeTo(out[0], 50.6970284911005, 1e-12) && out[0] == out[1] && out[1] == out[2]);
    CHECK(O2HLGReferenceEOTF(gray, 400, out) && closeTo(out[0], 30.7192948017577, 1e-12));
    CHECK(O2HLGReferenceEOTF(gray, 2000, out) && closeTo(out[0], 74.0574598112156, 1e-12));
    double red[3] = {1,0,0};
    CHECK(O2HLGReferenceOOTF(red, 1000, out));
    CHECK(closeTo(out[0], 765.406268293771, 1e-11) && out[1] == 0 && out[2] == 0);
    out[0] = out[1] = out[2] = 42;
    CHECK(!O2HLGReferenceEOTF(white, 399, out) && out[0] == 42 && out[1] == 42 && out[2] == 42);
    CHECK(!O2HLGReferenceOOTF(NULL, 1000, out));
    CHECK(!O2HLGReferenceOOTF(white, NAN, out));
    CHECK(!O2HLGReferenceOOTF(white, 2001, out));
    CHECK(!O2HLGReferenceOOTF(white, 1000, NULL));
    double bad[3] = {0.5, NAN, 0.5};
    CHECK(!O2HLGReferenceEOTF(bad, 1000, out) && out[0] == 42 && out[1] == 42 && out[2] == 42);
    CHECK(!O2HLGReferenceOOTF(bad, 1000, out) && out[0] == 42 && out[1] == 42 && out[2] == 42);
    puts("BT2100_REFERENCE_KERNEL_PASS_NO_CG_POLICY");
    return 0;
}
